// Dhall.Parser's foreign module (dhall/src/Dhall/Parser.js), which parses with the nearley grammar
// compiled from dhall/grammar.ne, ported for the compatibility corpus: earley.go is nearley's
// parser, grammar.go the grammar's rules (generated by dhall-parser/generate.ts) and
// postprocess.go the Go ports of the rules' postprocessors.
package Dhall_Parser_ffi

import "github.com/i-am-the-slime/iris-go/direct"

// ParseImpl implements parseImpl: every parse of the source, in nearley's order, as the values
// its postprocessors build, or null when the source does not parse.
func ParseImpl(source string) *[]any {
	results, parsed := parse(source)
	if !parsed {
		return nil
	}
	foreign := make([]any, len(results))
	for i, result := range results {
		foreign[i] = toForeign(result)
	}
	return &foreign
}

// toForeign gives a value the representation the Go backend reads a Foreign in: an object is an
// object table, and a field that Dhall.Parser reads with `unsafeCoerce :: Foreign -> Nullable
// Foreign` is a Nullable Foreign, a pointer that is nil for null.
func toForeign(value any) any {
	switch value := value.(type) {
	case []any:
		return toForeignArray(value)
	case *node:
		fields := toForeignArray(value.value)
		for _, field := range nullableFields[value.kind] {
			fields[field] = toNullable(fields[field])
		}
		if value.kind == "Union" {
			for _, alternative := range fields {
				alternative := alternative.([]any)
				alternative[1] = toNullable(alternative[1])
			}
		}
		return direct.ForeignRecord([]string{"type", "value"}, []any{value.kind, fields})
	}
	return value
}

// nullableFields are the positions in a node's value that Dhall.Parser decodes with decodeN.
// The alternatives of a Union are pairs of a label and such a field.
var nullableFields = map[string][]int{
	"Let":     {1},
	"Merge":   {2},
	"ToMap":   {1},
	"ListLit": {1},
	"Remote":  {4, 5},
}

func toForeignArray(values []any) []any {
	foreign := make([]any, len(values))
	for i, value := range values {
		foreign[i] = toForeign(value)
	}
	return foreign
}

func toNullable(value any) *any {
	if value == nil {
		return nil
	}
	return &value
}
